CREATE TABLE IF NOT EXISTS businesses (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,type ENUM('restaurant','hotel','event_centre') NOT NULL,slug VARCHAR(190) NOT NULL UNIQUE,logo_path VARCHAR(255) NULL,hero_image VARCHAR(255) NULL,phone VARCHAR(40) NULL,address TEXT NULL,status ENUM('active','suspended','inactive') NOT NULL DEFAULT 'active',account_status ENUM('pending_payment','active','suspended','inactive') NOT NULL DEFAULT 'active',onboarding_status ENUM('new','in_progress','complete') NOT NULL DEFAULT 'new',onboarding_step TINYINT UNSIGNED NOT NULL DEFAULT 1,onboarding_completed_at DATETIME NULL,trial_ends_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NULL,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('super_admin','owner','admin','manager','cashier','kitchen','reception','housekeeping','maintenance','waiter','runner','staff') NOT NULL DEFAULT 'staff',status ENUM('active','disabled') NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS outlets (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,type ENUM('restaurant','bar','pool','room_service','other') NOT NULL DEFAULT 'restaurant',status ENUM('active','inactive') DEFAULT 'active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE,INDEX(business_id));
CREATE TABLE IF NOT EXISTS locations (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NOT NULL,type ENUM('table','room','service') NOT NULL,name VARCHAR(120) NOT NULL,outlet_id INT UNSIGNED NULL,status ENUM('active','inactive') DEFAULT 'active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE,FOREIGN KEY(outlet_id) REFERENCES outlets(id) ON DELETE SET NULL,INDEX(business_id));
CREATE TABLE IF NOT EXISTS menu_categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NOT NULL,outlet_id INT UNSIGNED NULL,business_service_id INT UNSIGNED NULL,name VARCHAR(120) NOT NULL,sort_order INT NOT NULL DEFAULT 0,status ENUM('active','inactive') DEFAULT 'active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE,FOREIGN KEY(outlet_id) REFERENCES outlets(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS menu_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NOT NULL,category_id INT UNSIGNED NULL,business_service_id INT UNSIGNED NULL,name VARCHAR(160) NOT NULL,description TEXT NULL,price DECIMAL(12,2) NOT NULL DEFAULT 0,image_path VARCHAR(255) NULL,available TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES menu_categories(id) ON DELETE SET NULL,INDEX(business_id));
CREATE TABLE IF NOT EXISTS qr_codes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NOT NULL,location_id INT UNSIGNED NULL,outlet_id INT UNSIGNED NULL,token CHAR(32) NOT NULL UNIQUE,label VARCHAR(160) NOT NULL,status ENUM('active','inactive') DEFAULT 'active',scans BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE,FOREIGN KEY(location_id) REFERENCES locations(id) ON DELETE SET NULL,FOREIGN KEY(outlet_id) REFERENCES outlets(id) ON DELETE SET NULL,INDEX(business_id,status));
CREATE TABLE IF NOT EXISTS orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NOT NULL,outlet_id INT UNSIGNED NULL,location_id INT UNSIGNED NULL,qr_id BIGINT UNSIGNED NULL,order_number VARCHAR(30) NOT NULL,customer_name VARCHAR(120) NULL,customer_phone VARCHAR(40) NULL,status ENUM('new','accepted','preparing','ready','serving','served','completed','cancelled') NOT NULL DEFAULT 'new',payment_status ENUM('unpaid','paid','refunded') NOT NULL DEFAULT 'unpaid',payment_method ENUM('till','cash','card','transfer','online') NOT NULL DEFAULT 'till',total DECIMAL(12,2) NOT NULL DEFAULT 0,notes TEXT NULL,assigned_to INT UNSIGNED NULL,served_by INT UNSIGNED NULL,served_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL,FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE,FOREIGN KEY(outlet_id) REFERENCES outlets(id) ON DELETE SET NULL,FOREIGN KEY(location_id) REFERENCES locations(id) ON DELETE SET NULL,FOREIGN KEY(qr_id) REFERENCES qr_codes(id) ON DELETE SET NULL,INDEX(business_id,status,created_at));
CREATE TABLE IF NOT EXISTS order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,menu_item_id INT UNSIGNED NULL,item_name VARCHAR(160) NOT NULL,qty INT UNSIGNED NOT NULL,unit_price DECIMAL(12,2) NOT NULL,line_total DECIMAL(12,2) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(menu_item_id) REFERENCES menu_items(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS service_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NOT NULL,location_id INT UNSIGNED NULL,qr_id BIGINT UNSIGNED NULL,business_service_id INT UNSIGNED NULL,type VARCHAR(80) NOT NULL,message TEXT NULL,status ENUM('new','accepted','in_progress','completed','cancelled') DEFAULT 'new',assigned_to INT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL,FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE,FOREIGN KEY(location_id) REFERENCES locations(id) ON DELETE SET NULL,FOREIGN KEY(qr_id) REFERENCES qr_codes(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS push_subscriptions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NULL,endpoint TEXT NOT NULL,p256dh TEXT NULL,auth TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY endpoint_hash (business_id,endpoint(190)),FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS notification_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NULL,channel VARCHAR(30) NOT NULL,recipient VARCHAR(190) NULL,subject VARCHAR(190) NULL,body TEXT NULL,status VARCHAR(30) NOT NULL,response TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(business_id,created_at));
CREATE TABLE IF NOT EXISTS whatsapp_settings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NOT NULL UNIQUE,phone_number_id VARCHAR(100) NULL,access_token TEXT NULL,graph_version VARCHAR(30) NOT NULL DEFAULT 'v23.0',enabled TINYINT(1) NOT NULL DEFAULT 0,test_phone VARCHAR(40) NULL,FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS subscriptions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NOT NULL,plan_id INT UNSIGNED NULL,plan ENUM('trial','monthly','annual','lifetime') NOT NULL DEFAULT 'trial',starts_at DATETIME NOT NULL,ends_at DATETIME NULL,grace_ends_at DATETIME NULL,status ENUM('active','expired','cancelled','suspended') DEFAULT 'active',amount DECIMAL(12,2) NOT NULL DEFAULT 0,payment_reference VARCHAR(150) NULL,auto_renew TINYINT(1) NOT NULL DEFAULT 0,FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE,INDEX(business_id,status));
CREATE TABLE IF NOT EXISTS payment_submissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NOT NULL,subscription_id BIGINT UNSIGNED NULL,plan_id INT UNSIGNED NULL,amount DECIMAL(12,2) NOT NULL DEFAULT 0,payment_reference VARCHAR(150) NULL,proof_path VARCHAR(255) NOT NULL,proof_original_name VARCHAR(255) NULL,proof_mime VARCHAR(100) NULL,status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',review_note TEXT NULL,reviewed_by INT UNSIGNED NULL,submitted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,reviewed_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL,FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(subscription_id) REFERENCES subscriptions(id) ON DELETE SET NULL,FOREIGN KEY(plan_id) REFERENCES plans(id) ON DELETE SET NULL,FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE SET NULL,INDEX(business_id,status,created_at),INDEX(status,created_at));
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NULL,user_id INT UNSIGNED NULL,action VARCHAR(120) NOT NULL,details TEXT NULL,ip VARCHAR(45) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(business_id,created_at));
CREATE TABLE IF NOT EXISTS order_status_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,business_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NULL,from_status VARCHAR(30) NULL,to_status VARCHAR(30) NOT NULL,note TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(order_id,created_at),FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS service_request_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,request_id BIGINT UNSIGNED NOT NULL,business_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NULL,from_status VARCHAR(30) NULL,to_status VARCHAR(30) NOT NULL,note TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(request_id,created_at),FOREIGN KEY(request_id) REFERENCES service_requests(id) ON DELETE CASCADE,FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS customer_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NOT NULL,qr_id BIGINT UNSIGNED NULL,location_id INT UNSIGNED NULL,session_token CHAR(64) NOT NULL UNIQUE,last_seen_at DATETIME NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(business_id,last_seen_at));
CREATE TABLE IF NOT EXISTS notification_preferences (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL UNIQUE,sound_enabled TINYINT(1) NOT NULL DEFAULT 1,push_enabled TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS business_services (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,icon VARCHAR(20) NOT NULL DEFAULT '•',enabled TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY business_service(business_id,name),FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE);

-- SERV 2.1.0 platform, event and billing extensions
CREATE TABLE IF NOT EXISTS plans (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,code VARCHAR(50) NOT NULL UNIQUE,product_type ENUM('monthly','event') NOT NULL DEFAULT 'monthly',price DECIMAL(12,2) NOT NULL DEFAULT 0,currency VARCHAR(10) NOT NULL DEFAULT 'NGN',billing_interval VARCHAR(20) NOT NULL DEFAULT 'month',max_staff INT NULL,max_tables INT NULL,max_rooms INT NULL,max_menu_items INT NULL,max_services INT NULL,max_events INT NULL,max_guests INT NULL,features TEXT NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',sort_order INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS event_packages (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,code VARCHAR(50) NOT NULL UNIQUE,min_guests INT UNSIGNED NOT NULL DEFAULT 1,max_guests INT UNSIGNED NULL,price DECIMAL(12,2) NOT NULL DEFAULT 0,currency VARCHAR(10) NOT NULL DEFAULT 'NGN',features TEXT NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',sort_order INT NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NULL,package_id INT UNSIGNED NULL,name VARCHAR(180) NOT NULL,event_type ENUM('private','corporate','conference','seminar','wedding','other') NOT NULL DEFAULT 'private',organiser_name VARCHAR(160) NOT NULL,organiser_email VARCHAR(190) NULL,organiser_phone VARCHAR(40) NULL,venue VARCHAR(190) NULL,event_date DATE NOT NULL,start_time TIME NULL,end_time TIME NULL,guest_count INT UNSIGNED NOT NULL DEFAULT 0,table_count INT UNSIGNED NOT NULL DEFAULT 0,status ENUM('draft','scheduled','active','completed','cancelled') NOT NULL DEFAULT 'draft',amount DECIMAL(12,2) NOT NULL DEFAULT 0,payment_status ENUM('unpaid','paid','partial','refunded') NOT NULL DEFAULT 'unpaid',payment_reference VARCHAR(120) NULL,access_token CHAR(48) NULL UNIQUE,hero_image VARCHAR(255) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL,INDEX(business_id,event_date,status),INDEX(event_type,event_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS event_tables (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,event_id BIGINT UNSIGNED NOT NULL,table_number VARCHAR(40) NOT NULL,capacity INT UNSIGNED NOT NULL DEFAULT 1,qr_token CHAR(40) NOT NULL UNIQUE,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE,UNIQUE KEY event_table(event_id,table_number)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS event_guests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,event_id BIGINT UNSIGNED NOT NULL,table_id BIGINT UNSIGNED NULL,name VARCHAR(160) NOT NULL,email VARCHAR(190) NULL,phone VARCHAR(40) NULL,seat_number VARCHAR(30) NULL,invitation_token CHAR(48) NOT NULL UNIQUE,status ENUM('invited','checked_in','declined','served') NOT NULL DEFAULT 'invited',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE,FOREIGN KEY(table_id) REFERENCES event_tables(id) ON DELETE SET NULL,INDEX(event_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS event_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,event_id BIGINT UNSIGNED NOT NULL,table_id BIGINT UNSIGNED NULL,guest_id BIGINT UNSIGNED NULL,request_type VARCHAR(80) NOT NULL DEFAULT 'food',message TEXT NULL,status ENUM('new','accepted','preparing','ready','served','cancelled') NOT NULL DEFAULT 'new',assigned_to INT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL,FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE,FOREIGN KEY(table_id) REFERENCES event_tables(id) ON DELETE SET NULL,FOREIGN KEY(guest_id) REFERENCES event_guests(id) ON DELETE SET NULL,INDEX(event_id,status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payment_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NULL,event_id BIGINT UNSIGNED NULL,subscription_id BIGINT UNSIGNED NULL,type ENUM('subscription','event','upgrade','renewal','other') NOT NULL,amount DECIMAL(12,2) NOT NULL DEFAULT 0,currency VARCHAR(10) NOT NULL DEFAULT 'NGN',status ENUM('pending','successful','failed','refunded','offline') NOT NULL DEFAULT 'pending',reference VARCHAR(150) NULL UNIQUE,payer_name VARCHAR(160) NULL,payer_email VARCHAR(190) NULL,paid_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(business_id,created_at),INDEX(event_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS device_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NULL,token TEXT NOT NULL,platform VARCHAR(30) NOT NULL DEFAULT 'android',app_version VARCHAR(30) NULL,last_seen_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(business_id,status),INDEX(user_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS system_settings (setting_key VARCHAR(100) PRIMARY KEY,setting_value TEXT NULL,updated_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
